import { createRouter, createWebHistory, RouteRecordRaw } from 'vue-router'

import AuthLayout from '../layouts/AuthLayout.vue'
import AppLayout from '../layouts/AppLayout.vue'

import RouteViewComponent from '../layouts/RouterBypass.vue'

const routes: Array<RouteRecordRaw> = [
  {
    path: '/:pathMatch(.*)*',
    redirect: { name: 'city' },
  },
  {
    name: 'admin',
    path: '/',
    component: AppLayout,
    redirect: { name: 'city' },
    children: [
      { name: 'city', path: 'city', component: () => import('../pages/city/CityView.vue') },
      {
        name: 'bemExporter',
        path: 'bemExporter',
        component: () => import('../pages/preprocessing/city-bem/CityBemExporter.vue'),
      },
      { name: 'stl', path: 'stl', component: () => import('../pages/preprocessing/stl-converter/STLConverter.vue') },
      { name: 'stlMerge', path: 'stlMerge', component: () => import('../pages/preprocessing/stl-merge/STLMerger.vue') },
      {
        name: 'LbnlRedNodesToSTLConverter',
        path: 'LbnlRedNodesToSTLConverter',
        component: () => import('../pages/preprocessing/red-nodes-to-stl/LbnlRedNodesToSTLConverter.vue'),
      },
      {
        name: 'shp',
        path: 'shp',
        component: () => import('../pages/preprocessing/shp-to-geojson/ShpDBFConverter.vue'),
      },
      {
        name: 'geoJsonToShp',
        path: 'geoJsonToShp',
        component: () => import('../pages/preprocessing/geojson-to-shp/GeoJsonToShpConverter.vue'),
      },
      { name: 'osm', path: 'osm', component: () => import('../pages/preprocessing/osm-to-geojson/OSMConverter.vue') },
      { name: 'csv', path: 'csv', component: () => import('../pages/preprocessing/csv-to-geojson/CSVConverter.vue') },
      {
        name: 'geojsontocsv',
        path: 'geojsontocsv',
        component: () => import('../pages/preprocessing/geojson-to-csv/GeoJsonToCSVConverter.vue'),
      },
      {
        name: 'CSVandGeoJsonMerger',
        path: 'CSVandGeoJsonMerger',
        component: () => import('../pages/preprocessing/csv-geojson-merge/CSVandGeoJsonMerger.vue'),
      },
      {
        name: 'CSVandGeoJsonLBNLMerger',
        path: 'CSVandGeoJsonLBNLMerger',
        component: () => import('../pages/preprocessing/csv-geojson-lbnl-merge/CSVandGeoJsonLBNLMerger.vue'),
      },
      {
        name: 'plotlyGeojson',
        path: 'plotlyGeojson',
        component: () => import('../pages/preprocessing/geojson-plot/GeoJsonPlot.vue'),
      },
      {
        name: 'grib2',
        path: 'grib2',
        component: () => import('../pages/preprocessing/grib2-to-geojson/Grib2Converter.vue'),
      },
      {
        name: 'dashboard',
        path: 'dashboard',
        component: () => import('../pages/admin/dashboard/Dashboard.vue'),
      },
      {
        name: 'settings',
        path: 'settings',
        component: () => import('../pages/settings/Settings.vue'),
      },
      {
        name: 'preferences',
        path: 'preferences',
        component: () => import('../pages/preferences/Preferences.vue'),
      },
      {
        name: 'users',
        path: 'users',
        component: () => import('../pages/users/UsersPage.vue'),
      },
      {
        name: 'projects',
        path: 'projects',
        component: () => import('../pages/projects/ProjectsPage.vue'),
      },
      {
        name: 'payments',
        path: '/payments',
        component: RouteViewComponent,
        children: [
          {
            name: 'payment-methods',
            path: 'payment-methods',
            component: () => import('../pages/payments/PaymentsPage.vue'),
          },
          {
            name: 'billing',
            path: 'billing',
            component: () => import('../pages/billing/BillingPage.vue'),
          },
          {
            name: 'pricing-plans',
            path: 'pricing-plans',
            component: () => import('../pages/pricing-plans/PricingPlans.vue'),
          },
        ],
      },
      {
        name: 'faq',
        path: '/faq',
        component: () => import('../pages/faq/FaqPage.vue'),
      },
    ],
  },
  {
    path: '/auth',
    component: AuthLayout,
    children: [
      {
        name: 'login',
        path: 'login',
        component: () => import('../pages/auth/Login.vue'),
      },
      {
        name: 'signup',
        path: 'signup',
        component: () => import('../pages/auth/Signup.vue'),
      },
      {
        name: 'recover-password',
        path: 'recover-password',
        component: () => import('../pages/auth/RecoverPassword.vue'),
      },
      {
        name: 'recover-password-email',
        path: 'recover-password-email',
        component: () => import('../pages/auth/CheckTheEmail.vue'),
      },
      {
        path: '',
        redirect: { name: 'login' },
      },
    ],
  },
  {
    name: '404',
    path: '/404',
    component: () => import('../pages/404.vue'),
  },
]

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition
    }
    // For some reason using documentation example doesn't scroll on page navigation.
    if (to.hash) {
      return { el: to.hash, behavior: 'smooth' }
    } else {
      window.scrollTo(0, 0)
    }
  },
  routes,
})

export default router
